    change (1074072 + 32) with 1074104 in SBC. change (1074072 + 48) with 1074120 in RIC.
    assert (HDST : DST = FA + 4 * nf) by reflexivity. clearbody DST.
    pose proof (Z.div_mod SB 4096 ltac:(clear; lia)) as SBQ. rewrite SBA, Z.add_0_r in SBQ. set (sbq := SB / 4096) in SBQ. clearbody sbq. clear SBA.
    (* [comment removed for export] *)
    zstep. if_cases Kr; zify_cond Kr. { exfalso. clear -Kr RB. lia. }
    zstep. if_cases Kc; zify_cond Kc. { exfalso. clear -Kc CNT. lia. }
    zstep. rewrite (Z.shiftl_mul_pow2 nf 2) by (clear; lia). change (2^2) with 4.
    zstep. replace (FA + nf * 4) with DST by (rewrite HDST; clear; lia).
    zstep. rewrite (Z.shiftl_mul_pow2 cnt 2) by (clear; lia).
    zstep. replace (CHK + cnt * 4) with (CHK + 4 * cnt) by (clear; lia).
    replace (Z_to_bv 64 CHK) with (Z_to_bv 64 (CHK + 4 * 0)) by (f_equal; clear; lia).
    replace (Z_to_bv 64 DST) with (Z_to_bv 64 (DST + 4 * 0)) by (f_equal; clear; lia).
    (* [comment removed for export] *)
    callxA (eapply (rta_copy (Z.to_nat cnt) 0) with (F := F) (fc := fc) (m0 := m) (SRC := CHK) (DST := DST) (n := cnt) (ws := ws) (ds := ds) (W := []);
        [ clear -CNT; lia | clear -CNT; lia | clear -CNT; lia | exact LWS | clear -LDS; lia
        | exact CHK0 | exact CHK1 | clear -HDST HFA SB0 CB NF0; lia | clear -HDST HFA SB0 CB NF0 NFC CNT LDS HRI RI1; lia
